class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({ id: 'creek', sw: false, addOpen: false, sendOpen: false, pdfOpen: false, whyOpen: false, shareOn: false, pickId: '', addErr: false, off: {}, toast: '' }, {});
  }
  componentDidMount() {
    try { const h = (location.hash || '').slice(1); if (h) this.setState({ id: h }); } catch (e) {}
    this._k = (e) => { if (e.key === 'Escape') this.setState({ addOpen: false, sendOpen: false, pdfOpen: false, whyOpen: false }); };
    document.addEventListener('keydown', this._k);
  }
  componentWillUnmount() { document.removeEventListener('keydown', this._k); clearTimeout(this._tm); }
  say(t) { this.setState({ toast: t }); clearTimeout(this._tm); this._tm = setTimeout(() => this.setState({ toast: '' }), 4200); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), NB = ' ';
    const fm = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, NB);
    const price = (o) => fm(o.price) + NB + o.cur;
    const D = [
      { id: 'creek', name: 'Creek Residence', city: 'Дубай', co: 'ОАЭ', st: 'build', when: 'Сдача в 2027', kind: 'Апартаменты, 1-3 спальни', price: 1450000, cur: 'AED', dc: 5, beds: [1, 2, 3] },
      { id: 'marina', name: 'Marina Shore', city: 'Дубай', co: 'ОАЭ', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1-2 спальни', price: 1180000, cur: 'AED', dc: 7, beds: [1, 2] },
      { id: 'limassol', name: 'Limassol Gardens', city: 'Лимассол', co: 'Кипр', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 2-3 спальни', price: 310000, cur: 'EUR', dc: 0, beds: [2, 3] },
      { id: 'batumi', name: 'Batumi Sea Tower', city: 'Батуми', co: 'Грузия', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, студии и 1 спальня', price: 115000, cur: 'USD', dc: 5, beds: [0, 1] },
      { id: 'antalya', name: 'Antalya Hills', city: 'Анталья', co: 'Турция', st: 'build', when: 'Сдача в 2027', kind: 'Вилла, 3-4 спальни', price: 165000, cur: 'USD', dc: 7, beds: [3, 4] },
      { id: 'rawai', name: 'Proud Rawai Resort', city: 'Пхукет', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1-2 спальни', price: 3526000, cur: 'THB', dc: 7, beds: [1, 2] },
      { id: 'mira', name: 'Mira Coral Bay', city: 'Рас-эль-Хайма', co: 'ОАЭ', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 1-3 спальни', price: 555000, cur: 'AED', dc: 0, beds: [1, 2, 3] },
      { id: 'beverly', name: 'Beverly mountain Bay', city: 'Паттайя', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, студии и 2 спальни', price: 3195000, cur: 'THB', dc: 5, beds: [0, 1, 2] },
      { id: 'serene', name: 'Serene Raya Villas Bangjo', city: 'Пхукет', co: 'Таиланд', st: 'build', when: 'Сдача в 2027', kind: 'Вилла, 3-4 спальни', price: 22500000, cur: 'THB', dc: 7, beds: [3, 4] },
      { id: 'zenith', name: 'Zenith Pattaya II', city: 'Паттайя', co: 'Таиланд', st: 'plan', when: 'Сроки сдачи пока не названы', kind: 'Апартаменты, студии и 3 спальни', price: 3840000, cur: 'THB', dc: 5, beds: [0, 1, 2, 3] },
      { id: 'skypark', name: 'Skypark Celeste', city: 'Пхукет', co: 'Таиланд', st: 'ready', when: 'Можно въехать сейчас', kind: 'Апартаменты, 1 спальня', price: 5400000, cur: 'THB', dc: 7, beds: [1] },
      { id: 'tersane', name: 'Tersane Istanbul', city: 'Стамбул', co: 'Турция', st: 'build', when: 'Сдача в 2028', kind: 'Апартаменты, 1-3 спальни', price: 1125000, cur: 'USD', dc: 0, beds: [1, 2, 3] }
    ];
    const ST = { ready: ['ГОТОВ', 'badge--ok'], build: ['СТРОИТСЯ', ''], plan: ['ПЛАНИРУЕТСЯ', 'badge--muted'] };
    const d = D.filter((x) => x.id === S.id)[0] || D[0];
    const pc = (x) => String(+x.toFixed(2)).replace('.', ',');
    const o = { name: d.name, where: d.city + ', ' + d.co, price: price(d), when: d.when, kind: d.kind, tag: ST[d.st][0], tagCls: ST[d.st][1], hasShare: S.shareOn && !!d.dc, noShare: S.shareOn && !d.dc, shareOff: !S.shareOn, share: d.dc ? pc(d.dc * 0.45) + '%' : '' };
    const wv = (r) => r == null ? '-' : pc(r * d.dc / 100) + '%';
    const WR = [['Холодная база', 10, null, null], ['Запрос', null, 20, 25], ['Выбрана страна', 30, 35, 40], ['Выбран проект', 30, 40, 45]].map((r) => ({ t: r[0], c: wv(r[1]), w: wv(r[2]), h: wv(r[3]) }));
    const bw = (n) => n === 0 ? 'Студия' : (n === 1 ? '1 спальня' : (n < 5 ? n + ' спальни' : n + ' спален'));
    const plans = d.beds.map((n) => ({ t: bw(n), s: d.kind.indexOf('Вилла') === 0 ? 'Вилла' : 'Апартаменты' }));
    const COLL = [
      { id: 'c1', title: 'Квартира у моря, Дубай', sub: 'Для Дмитрия Орлова, объектов: 3' },
      { id: 'c2', title: 'Дом с садом, Лимассол', sub: 'Для Сергея Лукина, объектов: 4' },
      { id: 'c3', title: 'Квартира с видом, Дубай', sub: 'Для Павла Киселёва, объектов: 4' }
    ];
    const pickList = COLL.map((c) => ({ title: c.title, sub: c.sub, on: S.pickId === c.id, cls: S.pickId === c.id ? 'is-on' : '', pick: () => set({ pickId: c.id, addErr: false }) }));
    const PARTS = ['График платежей', 'О проекте', 'Лоты в продаже', 'Описание', 'Локация и карта', 'Планировки', 'Инфраструктура'];
    const pdfParts = PARTS.map((t) => ({ t: t, on: !S.off[t], cls: S.off[t] ? '' : 'is-on', toggle: () => set({ off: Object.assign({}, S.off, { [t]: !S.off[t] }) }) }));
    const close = () => set({ addOpen: false, sendOpen: false, pdfOpen: false, whyOpen: false });
    const channels = ['WhatsApp', 'Telegram', 'MAX', 'Почта'].map((t) => ({ t: t, go: () => { close(); this.say(t === 'Почта' ? 'В кабинете откроется письмо клиенту' : 'В кабинете откроется ' + t + ' со ссылкой для клиента'); } }));
    return {
      o: o, shareOn: S.shareOn, shareTitle: S.shareOn ? 'Скрыть мою долю' : 'Показать мою долю', toggleShare: () => set({ shareOn: !S.shareOn }), plans: plans, pickList: pickList, pdfParts: pdfParts, channels: channels,
      whyName: d.name, whyRows: WR, whyOpen: S.whyOpen, openWhy: () => set({ whyOpen: true }), closeWhy: () => set({ whyOpen: false }),
      addOpen: S.addOpen, sendOpen: S.sendOpen, pdfOpen: S.pdfOpen, addErr: S.addErr,
      swOpen: S.sw, swExp: S.sw ? 'true' : 'false', toggleSw: () => set({ sw: !S.sw }), others: D.map((x) => ({ t: x.name, cur: x.id === d.id ? 'true' : 'false', pick: () => set({ id: x.id, sw: false }) })),
      openAdd: () => set({ addOpen: true, addErr: false }), openSend: () => set({ sendOpen: true }), openPdf: () => set({ pdfOpen: true }), closeAll: close,
      submitAdd: () => { const c = COLL.filter((x) => x.id === S.pickId)[0]; if (!c) { set({ addErr: true }); return; } set({ addOpen: false, pickId: '' }); this.say('Добавлено в «' + c.title + '»'); },
      submitPdf: () => { close(); this.say('PDF собран. В кабинете он скачается на устройство'); },
      toastOn: !!S.toast, toast: S.toast, closeToast: () => set({ toast: '' })
    };
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); const f = HB.store.get('ui.objF'); if (f && f.shareOn) this.state.shareOn = true; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.toggleShare = () => { HB.store.set('ui.objF', Object.assign({}, HB.store.get('ui.objF') || {}, { shareOn: !S.shareOn })); set({ shareOn: !S.shareOn }); }; return v; }
}; })(Component);
